/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
replacements = {
    'qutebrowser/config/configdata.yml': [
        ('set-cmd-text -s :buffer', 'set-cmd-text -s :tab-select'),
    ],
    'tests/unit/completion/test_models.py': [
        ('miscmodels.buffer()', 'miscmodels.tabs()'),
        ('miscmodels.other_buffer(', 'miscmodels.other_tabs('),
        ('test_other_buffer_completion', 'test_other_tabs_completion'),
    ],
    'tests/end2end/features/completion.feature': [
        (':buffer', ':tab-select'),
    ],
    'tests/end2end/features/tabs.feature': [
        (':buffer', ':tab-select'),
    ],
    'tests/end2end/features/javascript.feature': [
        (':buffer', ':tab-select'),
    ],
    'tests/manual/completion/changing_title.html': [
        (':buffer', ':tab-select'),
    ],
}
for filename, pairs in replacements.items():
    path = Path(filename)
    content = path.read_text()
    for old, new in pairs:
        content = content.replace(old, new)
    path.write_text(content)
PY"

